import os
import re
import json
import math
import sqlite3
from typing import List, Dict, Any, Tuple

import pandas as pd

# Milvus
from pymilvus import connections, Collection, utility

# Optional embedding (fallback if you don't know how vectors were built, you can still run SQLite-only)
try:
    from sentence_transformers import SentenceTransformer
except Exception:
    SentenceTransformer = None


def connect_sqlite(path: str) -> sqlite3.Connection:
    if not os.path.exists(path):
        raise FileNotFoundError(f"SQLite db not found: {path}")
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def chunk_list(xs: List[str], n: int) -> List[List[str]]:
    return [xs[i:i+n] for i in range(0, len(xs), n)]


def build_in_clause(ids: List[str]) -> str:
    # Safe enough for controlled ids; for production use parameterized queries with executemany/temp tables.
    return "(" + ",".join(["'" + x.replace("'", "''") + "'" for x in ids]) + ")"


def try_milvus_connect(host: str, port: str) -> bool:
    try:
        connections.connect(alias="default", host=host, port=port)
        return True
    except Exception as e:
        print(f"[WARN] Milvus connect failed: {e}")
        return False


def get_collection_schema_fields(col: Collection) -> List[str]:
    try:
        return [f.name for f in col.schema.fields]
    except Exception:
        return []


def guess_vector_field(col: Collection) -> str:
    # Common names
    common = ["embedding", "vector", "emb", "clip_vector", "image_vector", "text_vector"]
    fields = get_collection_schema_fields(col)
    for c in common:
        if c in fields:
            return c
    # fallback: first FLOAT_VECTOR field
    try:
        for f in col.schema.fields:
            if str(f.dtype).endswith("FLOAT_VECTOR"):
                return f.name
    except Exception:
        pass
    raise RuntimeError(f"Cannot guess vector field for collection {col.name}. Fields={fields}")


def guess_id_fields(col: Collection) -> Dict[str, str]:
    # Return mapping keys: photo_id/review_id, business_id
    fields = set(get_collection_schema_fields(col))
    out = {}
    for k in ["photo_id", "review_id", "business_id"]:
        if k in fields:
            out[k] = k
    # Heuristics
    if "businessId" in fields and "business_id" not in out:
        out["business_id"] = "businessId"
    if "photoId" in fields and "photo_id" not in out:
        out["photo_id"] = "photoId"
    if "reviewId" in fields and "review_id" not in out:
        out["review_id"] = "reviewId"
    return out


def milvus_search_ids(
    collection_name: str,
    query_text: str,
    model,
    business_ids: List[str],
    topk: int = 200,
) -> pd.DataFrame:
    """Search Milvus by query_text; filter by business_ids if business_id field exists.
    Returns a dataframe with possible columns: business_id, photo_id/review_id, score.
    """
    if model is None:
        raise RuntimeError("No embedding model available; install sentence-transformers or adjust to your embedding pipeline.")

    if not utility.has_collection(collection_name):
        raise RuntimeError(f"Milvus collection not found: {collection_name}")

    col = Collection(collection_name)
    col.load()

    vec_field = guess_vector_field(col)
    id_fields = guess_id_fields(col)

    query_vec = model.encode([query_text], normalize_embeddings=True)

    # Build expr in chunks to avoid overly long expressions
    exprs = []
    if "business_id" in id_fields and business_ids:
        # Milvus expr expects JSON-like list strings
        # Example: business_id in ["id1","id2"]
        for ch in chunk_list(business_ids, 500):
            quoted = ",".join(["\"" + x.replace('"', '\\"') + "\"" for x in ch])
            exprs.append(f"{id_fields['business_id']} in [{quoted}]")
    else:
        exprs = [""]

    out_rows = []
    # Choose output fields
    output_fields = []
    for k in ["business_id", "photo_id", "review_id"]:
        if k in id_fields:
            output_fields.append(id_fields[k])

    for expr in exprs:
        try:
            res = col.search(
                data=query_vec,
                anns_field=vec_field,
                param={"metric_type": "IP", "params": {"nprobe": 10}},
                limit=topk,
                expr=expr if expr else None,
                output_fields=output_fields,
            )
        except Exception as e:
            raise RuntimeError(f"Milvus search failed on {collection_name}: {e}")

        for hits in res:
            for h in hits:
                ent = getattr(h, "entity", None)
                row = {"score": float(h.score)}
                if ent is not None:
                    # entity.get works in pymilvus
                    for f in output_fields:
                        try:
                            row[f] = ent.get(f)
                        except Exception:
                            pass
                out_rows.append(row)

    df = pd.DataFrame(out_rows)
    return df


def split_sentences(text: str) -> List[str]:
    # Simple sentence splitter
    if not isinstance(text, str) or not text.strip():
        return []
    parts = re.split(r"(?<=[\.!\?])\s+|\n+", text.strip())
    return [p.strip() for p in parts if p.strip()]


def extract_fresh_sentences(text: str) -> List[str]:
    sents = split_sentences(text)
    return [s for s in sents if re.search(r"\bfresh\b", s, flags=re.IGNORECASE)]


def main():
    # ----- Required exact configuration -----
    sqlite_paths = {
        "business": "D:/Yelp-JSON/db/sqlite3/business.db",
        "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
        "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
        "review": "D:/Yelp-JSON/db/sqlite3/review.db",
        "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
        "user": "D:/Yelp-JSON/db/sqlite3/user.db"
    }
    milvus_cfg = {
        'milvus_collections': {
            'reviews': 'reviews',
            'photos': 'photo_vector',
            'tips': 'milvus_tip'
        },
        'milvus_host': 'localhost',
        'milvus_port': '19530',
    }
    neo4j_cfg = {
        'neo4j_uri': 'bolt://localhost:7687',
        'neo4j_auth': ('neo4j', 'password')
    }
    # (neo4j not needed for this question)

    # ----- Connect SQLite -----
    conn_biz = connect_sqlite(sqlite_paths["business"])
    conn_photo = connect_sqlite(sqlite_paths["photo"])
    conn_review = connect_sqlite(sqlite_paths["review"])
    conn_user = connect_sqlite(sqlite_paths["user"])

    # Step 1: Tucson delis
    delis_df = pd.read_sql_query(
        """
        SELECT business_id, name, stars, address, city, state, postal_code, categories
        FROM business
        WHERE city = 'Tucson'
          AND categories LIKE '%Delis%'
        """,
        conn_biz,
    )
    if delis_df.empty:
        print(json.dumps({"results": [], "note": "No Tucson Delis found."}, ensure_ascii=False, indent=2))
        return

    delis_df["full_address"] = (
        delis_df["address"].fillna("") + ", " + delis_df["city"].fillna("") + ", " +
        delis_df["state"].fillna("") + " " + delis_df["postal_code"].fillna("")
    ).str.strip(" ,")

    business_ids = delis_df["business_id"].tolist()

    # Step 2: load photo metadata for these businesses
    # (table columns can vary; try a couple of common column names)
    # We'll query PRAGMA to detect columns.
    photo_cols = pd.read_sql_query("PRAGMA table_info(photo)", conn_photo)
    photo_colnames = set(photo_cols["name"].tolist())

    # Candidate columns
    select_cols = ["photo_id", "business_id"]
    for c in ["label", "caption", "text", "url"]:
        if c in photo_colnames:
            select_cols.append(c)

    in_clause = build_in_clause(business_ids)
    photos_df = pd.read_sql_query(
        f"SELECT {', '.join(select_cols)} FROM photo WHERE business_id IN {in_clause}",
        conn_photo,
    )

    # Step 3: find deli-counter photos (Milvus preferred; fallback keyword match)
    use_milvus = try_milvus_connect(milvus_cfg['milvus_host'], milvus_cfg['milvus_port'])

    model = None
    if SentenceTransformer is not None:
        # NOTE: This embedding may NOT match your Milvus photo vectors if they were built with CLIP.
        # If mismatch, Milvus results may be poor; the code still runs and will fallback.
        try:
            model = SentenceTransformer("all-MiniLM-L6-v2")
        except Exception as e:
            print(f"[WARN] Cannot load sentence-transformers model: {e}")
            model = None

    counter_photos_df = pd.DataFrame()
    counter_business_ids = business_ids

    if use_milvus and model is not None:
        try:
            mdf = milvus_search_ids(
                collection_name=milvus_cfg['milvus_collections']['photos'],
                query_text="deli counter",
                model=model,
                business_ids=business_ids,
                topk=300,
            )
            # Normalize field names if Milvus returns businessId/photoId
            # Attempt to find id columns
            cols = list(mdf.columns)
            biz_col = "business_id" if "business_id" in cols else ("businessId" if "businessId" in cols else None)
            pid_col = "photo_id" if "photo_id" in cols else ("photoId" if "photoId" in cols else None)

            if biz_col and pid_col and not mdf.empty:
                mdf = mdf.rename(columns={biz_col: "business_id", pid_col: "photo_id"})
                # Join with SQLite photo metadata for label/caption/url
                counter_photos_df = mdf[["business_id", "photo_id", "score"]].dropna().drop_duplicates()
                counter_photos_df = counter_photos_df.merge(photos_df, on=["business_id", "photo_id"], how="left")
                counter_business_ids = sorted(counter_photos_df["business_id"].dropna().unique().tolist())
            else:
                raise RuntimeError("Milvus photo search returned no usable id fields; falling back.")
        except Exception as e:
            print(f"[WARN] Milvus photo_vector search failed or unusable: {e}")
            counter_photos_df = pd.DataFrame()

    if counter_photos_df.empty:
        # Fallback: keyword filter on label/caption/text
        text_fields = [c for c in ["label", "caption", "text"] if c in photos_df.columns]
        if text_fields:
            pattern = re.compile(r"\b(counter|deli\s*counter|counter\s*service|display)\b", re.IGNORECASE)
            def row_match(r):
                for f in text_fields:
                    v = r.get(f, None)
                    if isinstance(v, str) and pattern.search(v):
                        return True
                return False
            counter_photos_df = photos_df[photos_df.apply(row_match, axis=1)].copy()
            counter_photos_df["score"] = None
            counter_business_ids = sorted(counter_photos_df["business_id"].dropna().unique().tolist())
        else:
            # If no text fields exist, we cannot determine counter photos without embeddings
            counter_photos_df = pd.DataFrame(columns=list(photos_df.columns) + ["score"])
            counter_business_ids = business_ids

    # Photo counts (total and counter-matched)
    total_photo_counts = (
        photos_df.groupby("business_id")["photo_id"].nunique().reset_index(name="total_photo_count")
        if not photos_df.empty else pd.DataFrame(columns=["business_id", "total_photo_count"])
    )
    counter_photo_counts = (
        counter_photos_df.groupby("business_id")["photo_id"].nunique().reset_index(name="counter_photo_count")
        if not counter_photos_df.empty else pd.DataFrame(columns=["business_id", "counter_photo_count"])
    )

    # Step 4: fetch reviews and find sentences mentioning "fresh"
    # We'll focus on businesses that have at least one counter photo if available.
    focus_biz_ids = counter_business_ids if len(counter_business_ids) > 0 else business_ids

    in_clause2 = build_in_clause(focus_biz_ids)
    review_cols = pd.read_sql_query("PRAGMA table_info(review)", conn_review)
    review_colnames = set(review_cols["name"].tolist())
    wanted_review_cols = [c for c in ["review_id", "business_id", "user_id", "stars", "date", "text"] if c in review_colnames]

    reviews_df = pd.read_sql_query(
        f"SELECT {', '.join(wanted_review_cols)} FROM review WHERE business_id IN {in_clause2}",
        conn_review,
    )

    # Optional: use Milvus to shortlist review_ids relevant to "fresh"
    fresh_review_ids = None
    if use_milvus and model is not None and not reviews_df.empty:
        try:
            mdf_r = milvus_search_ids(
                collection_name=milvus_cfg['milvus_collections']['reviews'],
                query_text="fresh",
                model=model,
                business_ids=focus_biz_ids,
                topk=500,
            )
            cols = list(mdf_r.columns)
            rid_col = "review_id" if "review_id" in cols else ("reviewId" if "reviewId" in cols else None)
            if rid_col and not mdf_r.empty:
                fresh_review_ids = set(mdf_r[rid_col].dropna().astype(str).tolist())
        except Exception as e:
            print(f"[WARN] Milvus reviews search failed: {e}")

    # Filter reviews: if we have fresh_review_ids, limit to those; else do text contains
    if not reviews_df.empty and "text" in reviews_df.columns:
        if fresh_review_ids is not None and "review_id" in reviews_df.columns:
            cand_reviews = reviews_df[reviews_df["review_id"].astype(str).isin(fresh_review_ids)].copy()
        else:
            cand_reviews = reviews_df[reviews_df["text"].str.contains(r"\bfresh\b", case=False, na=False)].copy()
    else:
        cand_reviews = pd.DataFrame(columns=reviews_df.columns)

    # Extract sentences containing fresh
    rows = []
    for _, r in cand_reviews.iterrows():
        text = r.get("text", "")
        sents = extract_fresh_sentences(text)
        for s in sents:
            rows.append({
                "business_id": r.get("business_id"),
                "review_id": r.get("review_id"),
                "user_id": r.get("user_id"),
                "review_stars": r.get("stars"),
                "review_date": r.get("date"),
                "fresh_sentence": s,
            })
    fresh_sentences_df = pd.DataFrame(rows)

    # Join user names
    if not fresh_sentences_df.empty and "user_id" in fresh_sentences_df.columns:
        user_ids = sorted(fresh_sentences_df["user_id"].dropna().astype(str).unique().tolist())
        if user_ids:
            user_cols = pd.read_sql_query("PRAGMA table_info(user)", conn_user)
            user_colnames = set(user_cols["name"].tolist())
            u_select = [c for c in ["user_id", "name"] if c in user_colnames]
            users_df = pd.read_sql_query(
                f"SELECT {', '.join(u_select)} FROM user WHERE user_id IN {build_in_clause(user_ids)}",
                conn_user,
            )
            if not users_df.empty:
                fresh_sentences_df = fresh_sentences_df.merge(users_df, on="user_id", how="left")
            else:
                fresh_sentences_df["name"] = None
        else:
            fresh_sentences_df["name"] = None
    else:
        if "name" not in fresh_sentences_df.columns:
            fresh_sentences_df["name"] = None

    # Step 5: assemble final output by business
    biz_df = delis_df[["business_id", "name", "stars", "full_address"]].copy()
    biz_df = biz_df.merge(total_photo_counts, on="business_id", how="left")
    biz_df = biz_df.merge(counter_photo_counts, on="business_id", how="left")
    biz_df["total_photo_count"] = biz_df["total_photo_count"].fillna(0).astype(int)
    biz_df["counter_photo_count"] = biz_df["counter_photo_count"].fillna(0).astype(int)

    # Prepare photo lists
    photo_out_fields = [c for c in ["photo_id", "label", "caption", "url", "score"] if c in counter_photos_df.columns]

    biz_to_photos: Dict[str, List[Dict[str, Any]]] = {}
    if not counter_photos_df.empty:
        for bid, g in counter_photos_df.groupby("business_id"):
            lst = []
            for _, pr in g.sort_values(by=("score" if "score" in g.columns else "photo_id"), ascending=False).head(30).iterrows():
                item = {k: (None if pd.isna(pr.get(k)) else pr.get(k)) for k in photo_out_fields}
                lst.append(item)
            biz_to_photos[str(bid)] = lst

    # Prepare review sentence lists
    biz_to_fresh: Dict[str, List[Dict[str, Any]]] = {}
    if not fresh_sentences_df.empty:
        for bid, g in fresh_sentences_df.groupby("business_id"):
            lst = []
            for _, rr in g.head(50).iterrows():
                lst.append({
                    "review_id": rr.get("review_id"),
                    "review_stars": rr.get("review_stars"),
                    "review_date": rr.get("review_date"),
                    "author": rr.get("name"),
                    "fresh_sentence": rr.get("fresh_sentence"),
                })
            biz_to_fresh[str(bid)] = lst

    results = []
    # Prefer businesses that have counter photos; if none, return all delis with empty photo list
    output_biz_df = biz_df[biz_df["business_id"].isin(focus_biz_ids)].copy() if focus_biz_ids else biz_df

    for _, b in output_biz_df.sort_values(["counter_photo_count", "stars"], ascending=[False, False]).iterrows():
        bid = str(b["business_id"])
        results.append({
            "business_id": bid,
            "business_name": b["name"],
            "address": b["full_address"],
            "rating_stars": float(b["stars"]) if b["stars"] is not None and not pd.isna(b["stars"]) else None,
            "photo_counts": {
                "total_photos": int(b["total_photo_count"]),
                "counter_related_photos": int(b["counter_photo_count"]),
            },
            "counter_photos": biz_to_photos.get(bid, []),
            "fresh_review_sentences": biz_to_fresh.get(bid, []),
        })

    print(json.dumps({
        "city": "Tucson",
        "category_filter": "Delis",
        "photo_query": "deli counter",
        "review_query": "fresh",
        "business_count": int(output_biz_df.shape[0]),
        "results": results
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

