import json
import ast
import sqlite3
from typing import Any, Dict, List, Tuple

import numpy as np

# Milvus
from pymilvus import connections, Collection, utility

# Embedding model
from sentence_transformers import SentenceTransformer


# ----------------------------
# Fixed configuration (must use these exact values)
# ----------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_cfg = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_cfg = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


# ----------------------------
# Helpers
# ----------------------------
def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def parse_attributes(attr_val: Any) -> Dict[str, Any]:
    """Best-effort parse Yelp 'attributes' which may be JSON, Python dict-string, or already a dict."""
    if attr_val is None:
        return {}
    if isinstance(attr_val, dict):
        return attr_val
    if isinstance(attr_val, (bytes, bytearray)):
        try:
            attr_val = attr_val.decode('utf-8', errors='ignore')
        except Exception:
            return {}
    if isinstance(attr_val, str):
        s = attr_val.strip()
        if not s:
            return {}
        # Try JSON
        try:
            return json.loads(s)
        except Exception:
            pass
        # Try Python literal dict
        try:
            v = ast.literal_eval(s)
            return v if isinstance(v, dict) else {}
        except Exception:
            return {}
    return {}


def truthy(v: Any) -> bool:
    if v is True:
        return True
    if v is False or v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() in {"true", "1", "yes", "y"}
    return False


def get_collection_and_fields(collection_name: str) -> Tuple[Collection, str, str, str]:
    """Return (collection, vector_field, business_id_field, text_id_field_guess).

    text_id_field_guess may be 'review_id'/'tip_id'/None depending on schema.
    """
    if not utility.has_collection(collection_name):
        raise RuntimeError(f"Milvus collection not found: {collection_name}")

    col = Collection(collection_name)
    col.load()

    # Find vector field
    vector_field = None
    scalar_fields = []
    for f in col.schema.fields:
        # DataType can vary by pymilvus version; safest: check 'dtype' name
        if str(getattr(f, 'dtype', '')).endswith('FLOAT_VECTOR') or str(getattr(f, 'dtype', '')).endswith('BINARY_VECTOR'):
            vector_field = f.name
        else:
            scalar_fields.append(f.name)

    if vector_field is None:
        raise RuntimeError(f"No vector field found in collection {collection_name}. Fields: {[f.name for f in col.schema.fields]}")

    # Guess business_id field
    business_id_field = None
    for cand in ["business_id", "businessId", "biz_id"]:
        if cand in scalar_fields:
            business_id_field = cand
            break

    # Guess id field (review_id/tip_id)
    text_id_field = None
    for cand in ["review_id", "tip_id", "id", "_id"]:
        if cand in scalar_fields:
            text_id_field = cand
            break

    return col, vector_field, business_id_field, text_id_field


def milvus_search_waterbowls(
    collection_name: str,
    embedder: SentenceTransformer,
    query_texts: List[str],
    topk: int = 2000,
    min_score: float = None
) -> List[Dict[str, Any]]:
    """Search Milvus and return list of hits with business_id (if present) and distance/score.

    Note: similarity metric may be IP/COSINE/L2; returned value is 'distance'.
    We keep it as 'distance' and rank by best (smallest for L2, largest for IP).
    """
    col, vector_field, business_id_field, text_id_field = get_collection_and_fields(collection_name)

    # Prepare output fields
    out_fields = []
    if business_id_field:
        out_fields.append(business_id_field)
    if text_id_field:
        out_fields.append(text_id_field)

    hits_all = []

    for qt in query_texts:
        qv = embedder.encode([qt], normalize_embeddings=True)
        qv = qv.astype(np.float32).tolist()

        # Search params: works for common indexes; adjust if needed.
        search_params = {"metric_type": "COSINE", "params": {"nprobe": 16}}

        results = col.search(
            data=qv,
            anns_field=vector_field,
            param=search_params,
            limit=topk,
            output_fields=out_fields
        )

        # results is a list (per query); we have 1 query
        for h in results[0]:
            ent = {}
            if business_id_field:
                try:
                    ent["business_id"] = h.entity.get(business_id_field)
                except Exception:
                    ent["business_id"] = None
            else:
                ent["business_id"] = None

            if text_id_field:
                try:
                    ent["text_id"] = h.entity.get(text_id_field)
                except Exception:
                    ent["text_id"] = None
            else:
                ent["text_id"] = None

            ent["distance"] = float(getattr(h, "distance", None))
            ent["query"] = qt
            ent["collection"] = collection_name

            if min_score is not None:
                # If metric is COSINE/IP, higher is better; if L2, lower is better.
                # We can't reliably know metric from schema; so do not hard filter by default.
                pass

            hits_all.append(ent)

    return hits_all


def fetch_text_snippet(sqlite_db: str, table: str, id_field: str, text_field: str, text_id: str) -> str:
    if not text_id:
        return ""
    conn = connect_sqlite(sqlite_db)
    try:
        cur = conn.execute(
            f"SELECT {text_field} FROM {table} WHERE {id_field} = ? LIMIT 1",
            (text_id,)
        )
        row = cur.fetchone()
        return (row[text_field] if row else "") or ""
    finally:
        conn.close()


# ----------------------------
# Main task: find pet-friendly restaurants in Metairie with outdoor seating and water bowls
# ----------------------------
def main():
    city = "Metairie"

    # 1) SQLite: candidate restaurants in Metairie; then parse attributes to enforce DogsAllowed & OutdoorSeating
    bconn = connect_sqlite(sqlite_paths["business"])
    try:
        cur = bconn.execute(
            """
            SELECT business_id, name, address, city, state, postal_code,
                   stars, review_count, categories, attributes
            FROM business
            WHERE city = ?
              AND categories LIKE '%Restaurants%'
            """,
            (city,)
        )
        rows = cur.fetchall()
    finally:
        bconn.close()

    candidate_businesses: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        attrs = parse_attributes(r["attributes"])
        dogs_allowed = truthy(attrs.get("DogsAllowed"))
        outdoor = truthy(attrs.get("OutdoorSeating"))
        if dogs_allowed and outdoor:
            candidate_businesses[r["business_id"]] = {
                "business_id": r["business_id"],
                "name": r["name"],
                "address": r["address"],
                "city": r["city"],
                "state": r["state"],
                "postal_code": r["postal_code"],
                "stars": r["stars"],
                "review_count": r["review_count"],
                "categories": r["categories"],
                "attributes": attrs,
            }

    if not candidate_businesses:
        print(json.dumps({
            "city": city,
            "candidates_found": 0,
            "results": [],
            "note": "No restaurants matched DogsAllowed=True and OutdoorSeating=True in the business table. Consider relaxing filters or relying on review text for dog-friendly/outdoor seating evidence."
        }, ensure_ascii=False, indent=2))
        return

    # 2) Milvus: vector search for 'water bowls' evidence in reviews and tips
    connections.connect(
        alias="default",
        host=milvus_cfg["milvus_host"],
        port=milvus_cfg["milvus_port"]
    )

    embedder = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")

    query_texts = [
        "they have water bowls for dogs",
        "water bowl for my dog",
        "provided a water bowl",
        "dog water bowl",
        "they brought my dog water",
        "a bowl of water for our dog"
    ]

    hits = []
    # reviews
    try:
        hits += milvus_search_waterbowls(
            milvus_cfg['milvus_collections']['reviews'],
            embedder,
            query_texts,
            topk=2000
        )
    except Exception as e:
        print(f"Warning: review vector search failed: {e}")

    # tips
    try:
        hits += milvus_search_waterbowls(
            milvus_cfg['milvus_collections']['tips'],
            embedder,
            query_texts,
            topk=2000
        )
    except Exception as e:
        print(f"Warning: tip vector search failed: {e}")

    candidate_ids = set(candidate_businesses.keys())

    # Keep only hits that can be mapped to candidate businesses
    mapped_hits = [h for h in hits if h.get("business_id") in candidate_ids]

    # 3) Score and (optionally) retrieve snippets from SQLite review/tip if IDs exist
    #    Note: distance meaning depends on metric; we use hit counts as primary rank.
    by_biz: Dict[str, Dict[str, Any]] = {bid: {
        **candidate_businesses[bid],
        "water_bowl_hit_count": 0,
        "evidence": []
    } for bid in candidate_ids}

    # detect if text_id likely belongs to review or tip by collection name
    for h in mapped_hits:
        bid = h["business_id"]
        by_biz[bid]["water_bowl_hit_count"] += 1

        snippet = ""
        text_id = h.get("text_id")
        if text_id:
            try:
                if h["collection"] == milvus_cfg['milvus_collections']['reviews']:
                    snippet = fetch_text_snippet(sqlite_paths["review"], "review", "review_id", "text", text_id)
                elif h["collection"] == milvus_cfg['milvus_collections']['tips']:
                    snippet = fetch_text_snippet(sqlite_paths["tip"], "tip", "tip_id", "text", text_id)
            except Exception:
                snippet = ""

        by_biz[bid]["evidence"].append({
            "source": "review" if h["collection"] == milvus_cfg['milvus_collections']['reviews'] else "tip",
            "text_id": text_id,
            "query": h.get("query"),
            "distance": h.get("distance"),
            "snippet": (snippet[:300] + ("..." if len(snippet) > 300 else "")) if snippet else ""
        })

    # Sort: primarily by hit count; secondarily by stars and review_count
    ranked = sorted(
        by_biz.values(),
        key=lambda x: (x["water_bowl_hit_count"], x.get("stars") or 0.0, x.get("review_count") or 0),
        reverse=True
    )

    # Keep top N and trim evidence per business
    top_n = 20
    for r in ranked[:top_n]:
        # keep up to 3 evidence items
        r["evidence"] = r["evidence"][:3]

    output = {
        "city": city,
        "candidates_found": len(candidate_businesses),
        "candidates_with_waterbowl_evidence": sum(1 for x in ranked if x["water_bowl_hit_count"] > 0),
        "results": ranked[:top_n],
        "notes": [
            "DogsAllowed/OutdoorSeating 来自 business.attributes（结构化字段）。",
            "Water bowls 通过 Milvus 对 reviews/tips 的语义检索获得证据；若 Milvus 集合未包含 business_id 或未包含 review_id/tip_id，将无法映射或回查原文。",
            "如结果偏少，可放宽结构化过滤（例如仅 OutdoorSeating=True），再用向量检索判断 pet-friendly 与 water bowls。"
        ]
    }

    print(json.dumps(output, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

